package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen0Test {

    @Test
    public void testAbbreviate_NullStr() {
        assertNull(WordUtils.abbreviate(null, 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_EmptyStr() {
        assertEquals("", WordUtils.abbreviate("", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_UpperIsNegativeOne() {
        // upper = -1 should set upper to str.length()
        // "hello" length is 5. upper becomes 5.
        // index of space is -1. upper (5) == str.length (5).
        // result: "hello"
        assertEquals("hello", WordUtils.abbreviate("hello", 0, -1, "..."));
    }

    @Test
    public void testAbbreviate_UpperGreaterThanLength() {
        // upper (10) > length (5). upper becomes 5.
        // result: "hello"
        assertEquals("hello", WordUtils.abbreviate("hello", 0, 10, "..."));
    }

    @Test
    public void testAbbreviate_UpperLessThanLower() {
        // lower = 5, upper = 2. upper becomes 5.
        // index of space in "hello world" starting at 5 is 5.
        // index (5) is not > upper (5), and index is not -1.
        // enters else block: substring(0, 5) + "..." -> "hello..."
        assertEquals("hello...", WordUtils.abbreviate("hello world", 5, 2, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInString_WithAbbreviation() {
        // str="hello", lower=0, upper=3, append="..."
        // index of space is -1.
        // upper (3) != length (5).
        // result: "hel" + "..."
        assertEquals("hel...", WordUtils.abbreviate("hello", 0, 3, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInString_NoAbbreviation() {
        // str="hello", lower=0, upper=5, append="..."
        // index of space is -1.
        // upper (5) == length (5).
        // result: "hello"
        assertEquals("hello", WordUtils.abbreviate("hello", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_SpaceAfterUpper() {
        // str="hello world", lower=0, upper=3, append="..."
        // index of space is 5.
        // index (5) > upper (3).
        // result: "hel" + "..."
        assertEquals("hel...", WordUtils.abbreviate("hello world", 0, 3, "..."));
    }

    @Test
    public void testAbbreviate_SpaceWithinUpper() {
        // str="hello world", lower=0, upper=6, append="..."
        // index of space is 5.
        // index (5) is not -1 and not > upper (6).
        // enters else block: substring(0, 5) + "..."
        // result: "hello..."
        assertEquals("hello...", WordUtils.abbreviate("hello world", 0, 6, "..."));
    }

    @Test
    public void testAbbreviate_NullAppendToEnd() {
        // Testing StringUtils.defaultString(appendToEnd) when null
        // str="hello", lower=0, upper=3, append=null
        // index -1, upper (3) != length (5).
        // result: "hel" + ""
        assertEquals("hel", WordUtils.abbreviate("hello", 0, 3, null));
    }

    @Test
    public void testAbbreviate_SpaceAtLowerBoundary() {
        // str="hello world", lower=5, upper=10, append="..."
        // index of space starting at 5 is 5.
        // index (5) is not -1 and not > upper (10).
        // result: substring(0, 5) + "..." -> "hello..."
        assertEquals("hello...", WordUtils.abbreviate("hello world", 5, 10, "..."));
    }
}
